/// Returns `true` iff `n` is prime under the definition:
/// `n >= 2` and for every `k` with `2 <= k < n`, `n % k != 0`.
///
/// Handles all `i8` values (negative, 0, 1 => `false`).
pub fn is_prime(n: i8) -> bool {
    // Values < 2 are not prime by definition.
    if n < 2 {
        return false;
    }

    // Loop over candidate divisors in increasing order.
    //
    // Invariants to maintain conceptually:
    // 1) n >= 2
    // 2) 2 <= d <= n
    // 3) For all j with 2 <= j < d: n % j != 0
    //
    // Termination measure (conceptual): n - d, which strictly decreases each iteration.
    let mut d: i8 = 2;

    while d < n {
        // If any divisor is found, immediately return false.
        if n % d == 0 {
            return false;
        }
        d += 1;
    }

    // If we reached here, then for all k with 2 <= k < n, n % k != 0.
    // Together with n >= 2, this implies n is prime by the given definition.
    true
}